// Source-stage/fused algorithms shared by native and Wasm.
fn quot(a:u32,b:u32,z:u32)->u32{if b==0{z}else{a/b}}
fn rem(a:u32,b:u32,z:u32)->u32{if b==0{z}else{a%b}}
#[no_mangle]pub extern "C" fn bench_alloc(n:usize)->*mut u32{let mut v=vec![0;n];let p=v.as_mut_ptr();std::mem::forget(v);p}
#[no_mangle]pub unsafe extern "C" fn bench_free(p:*mut u32,n:usize){drop(Vec::from_raw_parts(p,n,n));}
pub fn bench_scalar(case:u32,xs:&[u32],ys:&[u32],seed:u32,k:u32)->u64{match case{
0=>{let mut a=seed;for &x in xs.iter().rev(){a=(if (seed<k){(if (a<seed){(x).wrapping_add((a).wrapping_mul(k))}else{(x).wrapping_sub(a)})}else{(if (a>k){(a).wrapping_sub((x).wrapping_mul(seed))}else{(a).wrapping_add(x)})});}a as u64},
1=>{let mut a=seed;for &x in xs.iter().rev(){a=(if (seed<k){(if (x<seed){((a).wrapping_mul(k)).wrapping_add(x)}else{(a).wrapping_sub(x)})}else{(if (a<k){((x).wrapping_mul(k)).wrapping_add(a)}else{(x).wrapping_sub((a).wrapping_mul(seed))})});}a as u64},
3=>{let accepted:Vec<u32>=xs.iter().copied().filter(|&x|(rem(x,seed,0u32)<k)).collect();let mapped:Vec<u32>=accepted.iter().copied().map(|x|if (rem(x,seed,0u32)<k){(if (x<seed){(seed).wrapping_sub(x)}else{(x).wrapping_add(seed)})}else{(if (x>seed){(x).wrapping_sub(seed)}else{(x).wrapping_mul(k)})}).collect();let mut a=seed;for &x in mapped.iter().rev(){a=(if (a<seed){(x).wrapping_add((a).wrapping_mul(k))}else{(x).wrapping_sub(a)});}a as u64},
5=>{let accepted:Vec<u32>=xs.iter().copied().filter(|&x|(x>seed)).collect();accepted.first().copied().unwrap_or(seed) as u64},
6=>{let mut paired=Vec::new();for j in 0..xs.len(){let a=xs[j];let b=xs[j];paired.push((if (a<seed){(a).wrapping_add((b).wrapping_mul(k))}else{(a).wrapping_sub((b).wrapping_mul(k))}));}let mut acc=seed;for &v in paired.iter().rev(){acc=(if (acc<seed){(v).wrapping_sub(acc)}else{(v).wrapping_add((acc).wrapping_mul(k))});}acc as u64},
_=>panic!("non-scalar case")}}
#[no_mangle]pub unsafe extern "C" fn bench_eval(case:u32,xp:*const u32,xn:usize,yp:*const u32,yn:usize,seed:u32,k:u32,out:*mut u32)->usize{let xs=std::slice::from_raw_parts(xp,xn);let ys=std::slice::from_raw_parts(yp,yn);match case{
0=>{*out=bench_scalar(case,xs,ys,seed,k) as u32;1},
1=>{*out=bench_scalar(case,xs,ys,seed,k) as u32;1},
2=>{let accepted:Vec<u32>=xs.iter().copied().filter(|&x|(rem(x,seed,0u32)<k)).collect();let mapped:Vec<u32>=accepted.iter().copied().map(|x|if (rem(x,seed,0u32)<k){(if (x<seed){(seed).wrapping_sub(x)}else{(x).wrapping_add(seed)})}else{(if (x>seed){(x).wrapping_sub(seed)}else{(x).wrapping_mul(k)})}).collect();for(j,&v)in mapped.iter().enumerate(){*out.add(j)=v;}mapped.len()},
3=>{*out=bench_scalar(case,xs,ys,seed,k) as u32;1},
4=>{let mut paired=Vec::new();for j in 0..xs.len().min(ys.len()){let a=xs[j];let b=ys[j];paired.push((if (a<seed){(a).wrapping_add((b).wrapping_mul(k))}else{(a).wrapping_sub((b).wrapping_mul(k))}));}let mapped:Vec<u32>=paired.iter().copied().map(|v|(if (v>k){(v).wrapping_sub(seed)}else{(v).wrapping_add(seed)})).collect();for(j,&v)in mapped.iter().enumerate(){*out.add(j)=v;}mapped.len()},
5=>{*out=bench_scalar(case,xs,ys,seed,k) as u32;1},
6=>{*out=bench_scalar(case,xs,ys,seed,k) as u32;1},
7=>{let mapped:Vec<u32>=xs.iter().copied().enumerate().map(|(j,x)|{let i=j as u32;(if (rem(i,2u32,0u32)==0u32){(x).wrapping_add(k)}else{(x).wrapping_sub(seed)})}).collect();for(j,&value)in mapped.iter().enumerate(){*out.add(j)=value;}mapped.len()},
8=>{let mapped:Vec<u32>=xs.iter().copied().map(|x|{let mut v=x.wrapping_add(seed);v=rem(v.wrapping_mul(k.wrapping_add(1u32)).wrapping_add(x),4294967291u32,seed);v=rem(v.wrapping_mul(k.wrapping_add(3u32)).wrapping_add(x),4294967291u32,seed);v=rem(v.wrapping_mul(k.wrapping_add(5u32)).wrapping_add(x),4294967291u32,seed);v=rem(v.wrapping_mul(k.wrapping_add(7u32)).wrapping_add(x),4294967291u32,seed);v=rem(v.wrapping_mul(k.wrapping_add(9u32)).wrapping_add(x),4294967291u32,seed);v=rem(v.wrapping_mul(k.wrapping_add(11u32)).wrapping_add(x),4294967291u32,seed);v=rem(v.wrapping_mul(k.wrapping_add(13u32)).wrapping_add(x),4294967291u32,seed);v=rem(v.wrapping_mul(k.wrapping_add(15u32)).wrapping_add(x),4294967291u32,seed);v=rem(v.wrapping_mul(k.wrapping_add(17u32)).wrapping_add(x),4294967291u32,seed);v=rem(v.wrapping_mul(k.wrapping_add(19u32)).wrapping_add(x),4294967291u32,seed);v=rem(v.wrapping_mul(k.wrapping_add(21u32)).wrapping_add(x),4294967291u32,seed);v=rem(v.wrapping_mul(k.wrapping_add(23u32)).wrapping_add(x),4294967291u32,seed);v=rem(v.wrapping_mul(k.wrapping_add(25u32)).wrapping_add(x),4294967291u32,seed);v=rem(v.wrapping_mul(k.wrapping_add(27u32)).wrapping_add(x),4294967291u32,seed);v=rem(v.wrapping_mul(k.wrapping_add(29u32)).wrapping_add(x),4294967291u32,seed);v=rem(v.wrapping_mul(k.wrapping_add(31u32)).wrapping_add(x),4294967291u32,seed);v}).collect();for(j,&v)in mapped.iter().enumerate(){*out.add(j)=v;}mapped.len()},
_=>panic!("unknown case")}}
